// GENERATED preamble — every unit in the estate starts here, identically.
// Rejects an envelope whose MAJOR version this unit does not implement, rather than
// half-processing a shape it does not understand.
const SUPPORTED_MAJOR = 1;
const raw = $json.envelope ?? $json;
const v = String(raw.envelope_version ?? '0.0.0');
if (Number(v.split('.')[0]) !== SUPPORTED_MAJOR) {
  throw new Error('VALIDATION_FAILED: envelope_version ' + v + ' is not supported by plan.campaign.compose@1.0.0 (needs ' + SUPPORTED_MAJOR + '.x)');
}
for (const f of ['trace_id', 'tenant_id', 'idempotency_key']) {
  if (!raw[f]) throw new Error('VALIDATION_FAILED: envelope.' + f + ' is required');
}
if (raw.deadline_at && Date.parse(raw.deadline_at) < Date.now()) {
  // Fail fast rather than start work that cannot finish in time.
  throw new Error('TIMEOUT: deadline_at ' + raw.deadline_at + ' already passed before plan.campaign.compose started');
}
return [{ json: {
  ...raw,
  span_id: 'spn_' + Math.random().toString(36).slice(2, 10),
  parent_span_id: raw.span_id ?? null,
  policy: raw.policy ?? {},
  budget: raw.budget ?? {},
  provenance: raw.provenance ?? [],
  _started_at: Date.now(),
  _capability: "plan.campaign.compose",
  _capability_version: "1.0.0"
} }];

// GENERATED telemetry — span_start.
const e = $json;
return [{ json: { ...e, _telemetry: {
  event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
  trace_id: e.trace_id, span_id: e.span_id, parent_span_id: e.parent_span_id,
  tenant_id: e.tenant_id, brand_id: e.brand_id ?? null, vertical: e.vertical ?? null,
  capability: "plan.campaign.compose", capability_version: "1.0.0",
  layer: "terminal", stage: e.stage ?? null,
  event: 'span_start', at: new Date().toISOString()
} } }];

// GENERATED budget guard — injected because plan.campaign.compose declares a cost
// (estimate 5 minor units). A unit that can spend
// money never gets to decide for itself whether it may.
const ESTIMATE = 5;
const e = $json;
const b = e.budget ?? {};
const cap_ = b.cap_minor_units ?? null;
const spent = b.spent_minor_units ?? 0;
if (cap_ !== null && spent + ESTIMATE > cap_) {
  throw new Error('BUDGET_EXCEEDED: ' + (spent + ESTIMATE) + ' would exceed cap ' + cap_ + ' in plan.campaign.compose');
}
let tier = e.policy?.model_tier_cap ?? 'frontier';
const soft = b.soft_limit_pct ?? 0.8;
if (cap_ !== null && spent + ESTIMATE > cap_ * soft) {
  tier = { frontier: 'standard', standard: 'small', small: 'nano', nano: 'nano' }[tier] ?? 'small';
}
return [{ json: { ...e, policy: { ...(e.policy ?? {}), model_tier_cap: tier }, _budget_reserved: ESTIMATE } }];

// The model NEVER free-forms a pipeline. It picks from plays the vertical declared and
// that survive hard filters. Pre-filtering here is what makes the choice auditable.
const b = $json.payload.brief;
const profile = $json.payload.profile || {};
const plays = profile.plays || [];
const channels = new Set((b.channels || []).map(c => c.channel));
const excluded = new Set(profile.channels?.excluded || []);

const eligible = [], rejected = [];
for (const play of plays) {
  const reasons = [];
  if (play.objective && b.objective && play.objective !== b.objective) reasons.push('objective_mismatch');
  const needsVideo = play.steps.some(s => s.tag === 'assemble.video');
  const wantsVideo = (b.assets?.required_kinds || []).includes('video') || [...channels].some(c => ['tiktok', 'youtube'].includes(c));
  if (needsVideo && !wantsVideo && (b.budget_minor_units ?? Infinity) < 500) reasons.push('video_not_requested_and_budget_thin');
  if ([...channels].every(c => excluded.has(c))) reasons.push('all_channels_excluded_by_vertical');
  (reasons.length ? rejected : eligible).push({ id: play.id, title: play.title, when: play.when, steps: play.steps.map(s => s.tag), eliminated_by: reasons[0] || null });
}

return [{ json: { eligible: eligible.slice(0, 5), rejected, brief: b, profile } }];

